(function(){
  Object.keys(window.EDU_SUBJECT_BANKS).forEach(function(code){
    var b = window.EDU_SUBJECT_BANKS[code];
    b.tasks = [];
    for(var i=1;i<=18;i++){
      var taskCode = code + "-TASK-" + String(i).padStart(3,"0");
      b.tasks.push({
        code: taskCode,
        title: b.starterTitle + " - Task " + i,
        questions: b.starterQuestions
      });
    }
  });
})();

