  subject.pass = 40;
  subject.tasks = Array.isArray(subject.tasks) ? subject.tasks : [];

  function pad(n){ return String(n).padStart(3,"0"); }

  var answerPattern = ["B","C","A","D","B","A","D","C","B","A"];

  function buildQuestion(taskNo, qNo, item){
    var letters = ["A","B","C","D"];
    var correctLetter = answerPattern[(qNo + taskNo) % answerPattern.length];
    var opts = [];
    var wi = 0;
    for(var i=0;i<4;i++){
      if(letters[i] === correctLetter) opts[i] = item.correct;
      else opts[i] = item.wrongs[wi++];
    }
    return {
      q: "Read this context: " + item.ctx + "\n\n" + item.stem,
      o: opts,
      a: correctLetter,
      explanation: item.correct,
      type: "mcq"
    };
  }

  function makeTask(taskNo, pack){
    var code = "G10-ENG-FAL-TASK-" + pad(taskNo);
    var questions = (pack.items || []).map(function(item, i){
      var q = buildQuestion(taskNo, i, item);
      q.uid = code + "-Q" + String(i+1).padStart(2,"0");
      return q;
    });
    return {
      code: code,
      title: pack.title,
      pages: pack.pages || [],
      instructions: "Choose the best answer. Each question includes the context you need.",
      questions: questions
    };
  }

  function cloneQuestion(q, code, index){
    return {
      q: q.q,
      o: (q.o || []).slice(),
      a: q.a,
      explanation: q.explanation || "",
      type: "mcq",
      uid: code + "-Q" + String(index+1).padStart(3,"0")
    };
  }

