  subject.tasks = subject.tasks.filter(function(t){
    return !t || !/^G10-ENG-FAL-(TASK-\d{3}|PAPER-[12])$/.test(String(t.code || ""));
  });

  subject.tasks = subject.tasks.concat(dailyTasks).concat([paper1, paper2]);
  subject.tasks.sort(function(a,b){ return String(a.code || "").localeCompare(String(b.code || "")); });

  console.log("English FAL Term 3 loaded:", dailyTasks.length, "daily tasks,", all.length, "daily questions, 2 papers");
